quests[80334] = { id = 80334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shattered Spires", description = "With nothing to contain their arcane power, Dalaran's spires are crumbling.\n\nIf we let their energies continue to bleed out unchecked, that power could destabilize and destroy what is left of our forces.\n\nFind Aethas! He will know what to do.", completion = "Jaina yet lives?\n\nThank the Sunwell!\n\nThough none of us will survive long if we do not contain the energies of the spires.", objectives = "Find Aethas at the Tranquil Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80349] = { id = 80349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time to Return", description = "You'd best be on your way now. That portal should take you back to the village.", completion = "Excellent. I hope this expedites our research.", objectives = "Return to Moratari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80378] = { id = 80378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Light of the Dark", description = "The image of a purple candle, burning with glorious power springs unbidden to your mind as you contemplate the decaying filth before you, followed by a faint whisper echoing through your mind: \"One candle to rule them all, and in its brightness bind them.\"\n\nBring Janky the candlesmith in Gundargaz enough Coagulated Black Blood to forge a most unfortunate candle.", progress = "<Janky shivers as you approach.>\n\nAh!", completion = "Oh...Janky not normally turn down new candle, but you sure?", objectives = "Collect Coagulated Black Blood and bring it to Janky the kobold candlesmith in Gundargaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80380] = { id = 80380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloak and Needle", description = "Once you don your cloak, you will be able to find threads on any enemy.\n\nThe cloak will naturally absorb those threads, permanently increasing your power.\n\nTry collecting a thread from the nearby Infinite Ravagers.", progress = "You need not be a tailor. The cloak will weave threads for you.", completion = "You will find similar threads everywhere, from slain foes to looted treasures.", objectives = "Equip your Cloak of Infinite Potential and collect a Thread of Power from an Infinite Ravager.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80382] = { id = 80382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eggs in One Basket", description = "<This work order remains unfilled. Aliya Hillhelm would be quite happy if you helped complete the order.>", progress = "Inform Aliya that the work order is complete.", completion = "Thank you very much! We've been short-handed since Aunt Gerta left us. Every bit of help is appreciated.", objectives = "Collect 10 Hillhelm Eggs to place in this basket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80384] = { id = 80384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Keg-Stamped Package", description = "<A note, attached to a small and crumpled package, is shoved into your hands by a nondescript figure. Just as quickly, they disappear into the crowd. The letters on the note are scrawled crudely, as if by a dagger dipped in ink.>\n\nHere's yer share of the plunder.\n\nSent the mates to the inn.\n\n<You look around to see if there is anything else on the note. There is a picture of a keg at the bottom.\n\nYou shake the package gently and hear the telltale sound of coins.>", completion = "Got sent a package from Keg Leg, did ya? \n\nWell I can't say I really understand how you're involved in what we're doing, but it's not up to me to question the captain.\n\nTake a look at what I've plundered from around here. I'll give you some good stuff for those coins.", objectives = "Bring the Keg-Stamped Note to Da'kash Grimledger at the Roasted Ram Inn in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80385] = { id = 80385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Hurrah: Dragon Isles", description = "You've become quite popular with our allies, {name}!\n\nTo the south the Iskaara Tuskarr need your help with their community feast.\n\nTo the west the Maruuks have requested your aid with their hunts.\n\nTo the north the Obsidian Outcasts request your help reclaiming Dragonbane Keep.\n\nSounds like you have a full day ahead of you! Best of luck.", progress = "We're lucky to have you on our side, {name}.", completion = "Thanks to your efforts the Dragon Isles have been made all the safer.\n\nPlease accept this token of our appreciation.", objectives = "Assist the Tuskarr with their community feast, the Maruuk with their Hunt, and help reclaim Dragonbane Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80386] = { id = 80386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Hurrah: Zaralek Caverns and Time Rifts", description = "Our allies are once again requesting your aid, {name}.\n\nIn the Zaralek caverns the Dragonscale Expedition needs you to protect their researchers.\n\nWe're also concerned with the Zaqali invasions in the Ohn'ahran Plains and Azure Span.\n\nMeanwhile, the Bronze Dragonflight has asked for you to help them deal with temporal anomalies to the east of Valdrakken.\n\nHurry {name}, time is of the essence.", progress = "Do you bring news of your success?", completion = "I've heard great news from those you've helped, {name}.\n\nPlease accept this gift.", objectives = "Protect the Researchers under Fire, loot a Secured Shipment from a Suffusion Camp, and assist Soridormi in dispelling a Time Rift.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80388] = { id = 80388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Hurrah: Emerald Dream", description = "The druids call for aid!\n\nEnergy from the Emerald Dream is spreading across the Dragon Isles, please help them investigate it.\n\nThey also ask you travel to the Emerald Dream and assist Sprucecrown in creating a Superbloom.\n\nSome of the druids also wish for you to plant Dreamseeds in the Emerald Dream.\n\nPlease help them, {name}.", progress = "How are the druids doing?", completion = "My, the work you've done with the Emerald Dream is sure to help Azeroth heal.\n\nPlease accept this humble gift, along with our gratitude.", objectives = "Gather one hundred Dreamsurge Coalescence across the Dragon isles, assist Sprucecrown in creating a Superbloom, and plant 3 Dreamseeds of any quality in the Emerald Dream. Dreamseeds can be acquired from most activities in the Emerald Dream.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80389] = { id = 80389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Hurrah" }
quests[80392] = { id = 80392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Caretaker of Brunwin's Terrace", description = "Greetings, outlander. You must be the problem solver I've heard about! I'm Caretaker Batzvara. I tend to earthen who have gone into stasis, like our friend here.\n\nI often patrol Brunwin's Terrace to honor my fellow earthen with an offering of cinderbrew. Recently, however, I've drawn the attention of a local species of moles. They have a nose for sweets, and greedy claws for all else.\n\nYou look like you can defend yourself. Will you accompany me to pay respect to those who have gone into stasis?", completion = "Gratitude expressed. Your reputation as a stalwart ally is well-deserved.", objectives = "Offer cinderbrew to 6 inert earthen and kill 10 Sweetsnufflers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80394] = { id = 80394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Along for the Ride" }
quests[80395] = { id = 80395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Excavation" }
quests[80397] = { id = 80397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweets Seekers", description = "Earthen cinderbrew is a potent drink. It's dangerous to those who lack our constitution. Even worse, it has a sweet aroma that draws the attention of a vicious species of mole. They'll do anything to get their claws on it!\n\nAs I honor the earthen of Brunwin's Terrace with a sweet libation, my potent potable will draw their attention. If you're anywhere near me, be on your guard, so you can put down any who pop up.", objectives = "Kill 12 sweetsnufflers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80399] = { id = 80399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rations and Revelations", description = "We found these prisoners fleeing a nearby nerubian military base.\n\nThe circumstances of their escape are... unclear, even to them. As if someone else created the opening they needed to escape.\n\nThey need rest, but we need to find out what happened in there.\n\nFood first. Maybe once they've regained some of their strength, they'll remember something.", progress = "We managed to throw together a simple stew of sorts. It's not the tastiest, but it has to be better than whatever they had to eat in spider prison.", completion = "These people have been through so much. Civilians--not even soldiers. Most of them didn't sign up for this. And yet they became prisoners of war.\n\nIf anything back at the nerubian base could give us an advantage, we have to take it.", objectives = "Hand out 3 Arathi Rations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80401] = { id = 80401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perfect Sponge", description = "Welcome, stalwart colleague, to Shimmermist Falls! It's always damp here--a thriving paradise for green, living things. Unfortunately, it's also the perfect climate for moss to grow on my inert earthen charges. \n\nWe'll need to gather a few supplies for removing the moss. First, we need a sponge to wash their surfaces. It needs to be soft enough to not damage them but strong enough to hold up to an earthen's rough stone skin. \n\nThe caps from the lashrooms down below are perfect!", progress = "These lashroom caps make for perfect sponges!", completion = "Task complete! This one is perfect! And your performance is optimal, of course.", objectives = "Collect one perfect lashroom cap.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80402] = { id = 80402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buckets and Blooms", description = "Down among the creeping lashrooms grows an orange flower. When mixed with water, its blooms make a caustic solvent that is perfect for removing moss from earthen skin.\n\nI also left a bucket next to this earthen the last time I was here, which I use to make the solvent. Something seems to have made off with it.\n\nCould I delegate the task of gathering these to you? I'll wait here. The moles from the terrace have given me enough excitement for one day.", progress = "The acidity from the plants is strong enough to remove the moss but gentle enough not to harm the earthen. Plus it has a pleasing smell to it. Almost like sulfur.", completion = "Ah, I can smell the sulfur from here! Thank you for gathering the bucket and blooms.\n\nNot everyone shares my taste, but I enjoy a bowl of lightly seared magma in an igneous bowl, especially when the fumes are particularly sulfurous. \n\nWhat? You've never tried it? To each their own.", objectives = "Collect 8 caustic blooms and find the missing bucket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80404] = { id = 80404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mossy Earthen", description = "Excellent work gathering everything together. I've mixed the solvent for you. \n\nNow all that's left is to gently clean off our mossy friends down there.", progress = "Let's get these folks cleaned up.", completion = "That's much better! Earthen should be firm stone, not soft fuzz.", objectives = "Tend to 4 mossy earthen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80405] = { id = 80405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Much Drip", description = "This is Ausgazur. His hand is usually full of a selection of his favorite gems. We don't really know what it's like when we go into stasis, but he wanted to spend his last moments contemplating the natural beauty of Azeroth and her bounty.\n\nI am afraid someone or something has made off with the jewels he usually holds. Let's look around. See if you can find any clues where they may have gone off to.", progress = "Ausgazur will never forgive me if his gems go missing. This is very upsetting. Who would steal from an earthen in stasis?", completion = "Kobolds made off with his gems? This is unacceptable! We must recover the rest of Ausgazur's jewels!", objectives = "Examine Ausgazur for clues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80406] = { id = 80406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Ausgazur's Gems", description = "So it was kobolds who made off with Ausgazur's gems. I did not realize the Waterworks was under attack. Our timing is lucky for the defenders down below! \n\nWe must get those jewels back! I'll stay here and guard the remaining gems, but I implore you to complete a critical task: go down into the Waterworks and retrieve the rest.", progress = "We need to find the rest of Ausgazur's gems! Critical priority!", completion = "Excellent work! Though they're not worth much monetarily, these gems meant a great deal to Ausgazur. I am glad he will not be parted from them any longer.", objectives = "Recover 4 of Ausgazur's gems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80407] = { id = 80407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glintwick the Gem Grabber", description = "The kobold mentioned Glintwick, did he? It sounds like she's the driving force behind these gem thieves. I'll bet my beard she's got Ausgazur's last gem!\n\nLook for her in the Waterworks and see if she has the final gem. She may also be behind the attack that's happening, so taking her out will help the defenders.", progress = "Glintwick will not get away with this thievery!", completion = "You did it! You found the last gem! I'm glad that Glintwick will no longer be after Ausgazur's gems.\n\nThis particular gem was his favorite. It's not faceted, like the rest. Ausgazur could always find the beauty in flawed things. He would show me this one and marvel at its hue and potential. He never wanted it buffed or shined.\n\n<She's silent a moment, then looks at the gray earthen beside her.>\n\nAh, Ausgazur. You never cared what I looked like either. You saw my potential. I miss you, friend.", objectives = "Kill Glintwick.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80408] = { id = 80408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shimmermist Falls", description = "West of Gundargaz is another green space - a lovely area with waterfalls and more terraces. My schedule takes me in that direction next, and I would be very glad of your company to help deal with the wildlife there as well. \n\nIf your other duties are not pressing, let us meet there.", completion = "You made it! Let us get to work.", objectives = "Meet Batzvara in Shimmermist Falls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80409] = { id = 80409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Polarized" }
quests[80412] = { id = 80412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fending off Darkness" }
quests[80426] = { id = 80426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid the Shado-Pan", progress = "The Shado-Pan would appreciate any aid you can provide to our cause.", completion = "You are not only a skilled fighter, but generous! Thank you, {name}." }
quests[80427] = { id = 80427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid the Golden Lotus", progress = "Have you come to aid us?", completion = "Great! Keep up your training and we'll be ready for anything!" }
quests[80429] = { id = 80429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid the August Celestials", progress = "The sha force us to consider what is worth fighting for. What will you give for the future of Pandaria?", completion = "You are brave and honorable." }
quests[80430] = { id = 80430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid the August Celestials", progress = "Have you offerings for the mighty Black Ox?", completion = "Stand proud and fight swiftly." }
quests[80431] = { id = 80431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid the August Celestials", progress = "Greetings, challenger. I will accept your donations to my temple.", completion = "Fight with strength and honor." }
quests[80433] = { id = 80433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid the August Celestials", progress = "To practice is to improve oneself. To give is to improve one's community.", completion = "You bring honor." }
quests[80434] = { id = 80434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Deeps", description = "Onward and downward it is, then. We'd best follow after Speaker Brinthe and see what state the nerubians have left her home in.\n\nMagni, Dagran, and I will accompany you down in due time. Would you mind roving ahead and making sure there's a warm welcome awaiting us?", completion = "By the Titans! It looks like the nerubians did a number on our station... but I see no spidery fiends here. Only struggling Machine Speakers...", objectives = "Find Speaker Brinthe at the bottom of the Coreway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80438] = { id = 80438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid the Horde", progress = "Lok-tar, {name}. What aid do you bring?", completion = "For the Horde!" }
quests[80439] = { id = 80439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid the Alliance", progress = "King Varian requests your aid, {name}. Have you any supplies?", completion = "A soldier's duty is never done." }
quests[80441] = { id = 80441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid the Order of the Cloud Serpent", progress = "The Cloud Serpents rely on favorable winds. Have you any fortune for us?", completion = "Excellent. May you ride fair winds on your journey." }
quests[80442] = { id = 80442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid the Sunreavers Onslaught", progress = "My scouts report enemy activity. Have you any supplies to bring fortune to our troops?", completion = "Very good, we shall ready a counterattack." }
quests[80443] = { id = 80443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid the Kirin Tor Offensive", progress = "There will be no victory without bloodshed. Have you brought aid, {class}?", completion = "I will add these to the coffers." }
quests[80444] = { id = 80444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid the Anglers", progress = "Hey buddy! Fish up any charms recently? The locals say they bring luck to the waters.", completion = "Thanks a million! We're sure to catch a great haul with this!" }
quests[80446] = { id = 80446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking for Group", description = "There's my favorite champion!\n\nIf you are in need of a mark to hunt, I know a few dungeons worth exploring.", progress = "How goes the dungeon delving?", completion = "I knew you could do it!", objectives = "Defeat 3 dungeon bosses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80447] = { id = 80447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking for More", description = "You think you're tough?\n\nI'll believe it when you take on a real challenge.\n\nDefeat the most powerful foes on Pandaria and we'll see how tough you really are.", progress = "The real challenge is finding enough other puny elf to team up with.", completion = "I guess you're pretty tough after all!", objectives = "Defeat 2 raid bosses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80448] = { id = 80448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fresh Scene", description = "Uh-uh honey, I'm not gonna let you spend all day in stuffy dungeons where no one can see your getup!\n\nPut on your going-out look and let's get you somewhere fresh!", progress = "You wouldn't catch me dead in a dungeon, nuh-uh. You know what's down there? Mud! Cobwebs! People wearing those shoulderpads way too big for 'em.\n\nNo sir, I'll stay right here, thank you.", completion = "Ooh honey, I can tell you've been somewhere good.\n\nTell me all about it!", objectives = "Complete a scenario.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80456] = { id = 80456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sassy Arathi", description = "I had heard that an Arathi was making trouble in the city. It sounds like he is butting heads with the peacekeepers.\n\nYou've worked with the Arathi before, haven't you? Maybe you'd be able to smooth over any ruffled feathers.", completion = "Yes, how can I help you?", objectives = "Speak to Peacekeeper Leif in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80457] = { id = 80457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Serving the Queen" }
quests[80500] = { id = 80500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bronzebeard Family", description = "<Moira takes a deep, centering breath.>\n\nWe need to let Brann and my son Dagran know what happened. They're at Dalaran's visitor center.\n\nCould ye go get them for me? Father needs his family right now.", progress = "My son always has been the scholarly sort. Takes after his father in that way...\n\nWe're all quite proud of him.", completion = "It's good for us to all be in one room together, even if the reason is so dire. My father hasn't really been a... part of Dagran's life. But I mean to change that, you have my word.\n\nThank ye, {name}.", objectives = "Head to Brann and Dagran in the Dalaran Visitor Center to inform them of what has happened to Magni.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80502] = { id = 80502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Cry for Me, Azj-Kahet", description = "<You find a crumpled page of journal paper wrapped around a small key.>\n\nI always suspected Arax'ne was a traditionalist, but I didn't think she'd go this far. I don't know where I'm going, but I just have to get away from her.\n\nTo whoever finds this, it means the worst has come to pass. This key unlocks a chest that contains all my worldly possessions. They are yours.\n\nAll I ask is that you avenge me by slaying Arax'ne.", progress = "The key glints silver in the light of Azj-Kahet.", completion = "The contents of this chest now belong to you.\n\n--Klaskin", objectives = "Avenge Klaskin and kill Arax'ne in the Umbral Bazaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80508] = { id = 80508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dread in the Den", description = "You kobold friend, yes? Need help. Bad things happening in the Chittering Den. \n\nGlumtooth Gang setting up camp. Cronies of Candle King, want war with earthen.\n\nCan't stop them alone. Meet me at camp.", completion = "You came. Good. Much to do. Much to protect.", objectives = "Meet Scrit at her camp in the Chittering Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80509] = { id = 80509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Suit of Slime", description = "Glumtooth Gang no let you into camp looking like that. Need disguise. Make you look like bug, then we walk right in.\n\nFirst, need wax. Plenty here. Take from slime beasts or scrape off hoppers. \n\nThen we stick wax on you. Stick bug bits to wax. Perfect disguise.", progress = "With right disguise, no one know you not bug.", completion = "That everything. Soon you look just like bug.", objectives = "Collect 20 Sticky Wax from Waxy Runoffs and Wax-addled Hoppers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80510] = { id = 80510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Healing the Headwaters", description = "Glumtooth Gang so wasteful! They leave much scrap in the water. Bad for water. Bad for scrap. Go clean it up.", completion = "Much better. Make no sense to let scrap rot in pool.", objectives = "Remove 6 Waxy Scrap.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80511] = { id = 80511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Casing the Camp", description = "Now we take you to camp. You see what Boss Whiskerlash do. Put on bug disguise when we close to camp. Let me do talking.", progress = "Can no let this camp stand. Too much to lose for kobold and earthen.", completion = "You see what Glumtooth Gang do? Even have earthen prisoner!", objectives = "Investigate the Glumtooth Gang camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80512] = { id = 80512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beat the Best", description = "If Glumtooth Gang succeed, this earthen first captive of many. We need free him.\n\nHe prize. Every kobold here want fight him. Must earn our place.\n\nYou beat up strong bugs, they think me strong trainer. Then they let you into ring.\n\nMay best bug win.", progress = "Beat other three contenders and we can rescue the earthen.", completion = "Nice work! You really fight like bug.", objectives = "Defeat the bug-trainers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80513] = { id = 80513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snouty Sabotage", description = "You need good distraction to get earthen out. I need Glumtooth Gang stopped. Have perfect thing for both.\n\nSome fool mix Cinderbrew with candle wax in the Warrens. Candles burn normal at first, then boom. Big boom. Place around camp. Explosions good distraction for escape.\n\nWhile you at it, loosen some bug leashes. Let Glumtooth Gang see how scary bugs are.", progress = "Boss Whiskerlash regret day he help turn kobolds to war.", completion = "Perfect, you have good distraction when time come. Can't wait.", objectives = "Place Cinder-Flash Candles and loosen bug leashes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80514] = { id = 80514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break out Berrund!", description = "You work good. Now they let you into ring to \"fight\" earthen. You go to ring when ready. Cinder-flash candles could go off any moment.\n\nI head back to camp. Wait for you and earthen there.\n\nYou good one. No get killed.", completion = "Captured? No, I was just gathering information. And I've got bad news.", objectives = "Escort Berrund from the camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80515] = { id = 80515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put the Shine On", description = "Hate to admit, but loud earthen right. Boss Whiskerlash have strongest bugs. But everything have weakness.\n\nSpiders afraid of light, and our friend very shiny. If we make him shinier, no spider want to fight.\n\nGlumtooth Gang been capturing candleflies. Free them and rub off some glow dust. We make big earthen big shiny!", progress = "This better not go to his head.", completion = "Yes, this perfect. With this he really gleam!", objectives = "Free Candleflies and collect their luminescence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80516] = { id = 80516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bump off the Boss", description = "That kobold knows her stuff. Scrit says Boss Whiskerlash has his own cadre of spiders in a cave nearby. Don't worry, I'll lead the charge. \n\nCome on, we've got a boss to take down.", completion = "You back! Berrund came back alone. Scrit worried.\n\nIt done then? Good. Glumtooth Gang no last long without leader.", objectives = "Slay Boss Whiskerlash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80517] = { id = 80517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Where it Began", description = "<Zee-Zee is ready to head back to the Deepforge Golemworks.>", completion = "Good, you're here. I hope you're ready, {name}.", objectives = "Meet up with Brinthe and Dagran outside the Deepforge Golemworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80558] = { id = 80558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nothing Ventured", description = "These niffen have been down here a long time--long enough to build a village and set up trade with the nerubians. Some of them are even able to trade in that big nerubian city!\n\nThe goblins, though? They're from the Venture Company. No wonder General Anub'azal was skeptical of me, if he's used to dealing with them.\n\nWhat are they doing all the way down here? Let's try to learn what led them to this place.", progress = "Take a good look around for loose-lipped goblins.", completion = "At least they're willing to talk to you, even if they are rude. Maybe you can convince them working together is mutually beneficial.\n\nTry something a little... transactional. They'll appreciate that.", objectives = "Learn what you can from the goblins in Mmarl.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80562] = { id = 80562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blossoming Delight", description = "Few followers of the light would dare to attempt the dish I plan to make. A mix of traditional Imperial spices combined with the forbidden harvest of the nearby fungal blooms.\n\nThis dish will delight the palate and remind one of the adventurous spirit that founded the Hallowfall expedition.\n\nPlease journey to the Mycomancer Cavern nearby and harvest the blooms I require.", progress = "Have you found all of the ingredients?", completion = "Now the magic happens. Please sample this creation for yourself.", objectives = "Collect 20 Ever-Blossoming Fungi from Mycromancer Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80563] = { id = 80563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tool of Attunement", description = "The nerubians must have some means of cleansing themselves after Black Blood exposure. If they did not, they would not have been so successful in their harvesting operation.\n\nIf necessary, I can pick up on the harmony of this world with ease to restore my mind to this reality. But for your sake and Hannan's, we should probably obtain whatever it is they use.\n\nAlthough we can spare the trouble... if you don't mind the threat of forever splitting your consciousness between two realities.", progress = "The nerubians must have something on them to cleanse their minds after such direct proximity to the Black Blood.", completion = "A tuning crystal? Fascinating.\n\nThough I cannot say I'm too impressed with the solution. They brought this problem upon themselves, after all.", objectives = "Find a Tuning Crystal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80564] = { id = 80564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Research", description = "The nerubians are harvesting Black Blood nearby.\n\nIf allowed to persist, the corruption caused by excavating the veins may spread. It will continue until it consumes everything.\n\nI have no intention of sitting and waiting for it to taint the roots. I am trying to learn and understand their methods... so that I may strike at the heart of the operation.\n\nYou're welcome to join me.\n\nIf, of course, you would also prefer your world not to drown in oozing pools of Black Blood.", progress = "These disgusting pustules, the veins of corruption... this is only the beginning of the damage this horrific operation could cause.", completion = "Here in the center of all of this corruption, I hear something calling to me. It pounds in my head like a drum.\n\nI cannot just ignore it.", objectives = "Investigate the Black Blood harvesting site.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80565] = { id = 80565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resounding Repercussions", description = "I did not mean for...\n\n<Orweyna's eyes narrow.>\n\nFetch him, {name}. You were exposed to the Black Blood, too. But Hannan took most of it.\n\nHe has entered the Unseeming, his mind shifted to a realm beyond our eyes through exposure to the Black Blood. You may need to join him, however far in he ventured, to retrieve him.\n\nI will activate the nerubian cleansing instrument for when you return.\n\nDo not lose yourself in that altered state.", progress = "Is this real? Am I imagining the monsters?", completion = "My head... It hurts. Everything feels so cloudy and... Help, please!", objectives = "Retrieve Hannan from the Abandoned Harvest Site inside the cave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80566] = { id = 80566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Abound", description = "<Hannan is barely responsive and less corporeal than he should be, lost deeper in the Unseeming than you.>\n\nSome of the canisters exploded... Then the spiders appeared.\n\nKill the--kill the spiders!", completion = "Hmm. I have noticed you seem good at surviving challenging tasks. I will remember this about you.", objectives = "Find and kill the spiders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80567] = { id = 80567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Song of Restoring", description = "<Orweyna looks relieved at the sight of Hannan, but does not seem dissuaded from her task.>\n\nI cannot say I am surprised at what you found in that cave. Nerubians stuck in the Unseeming, trapped in a realm of monsters and madness...\n\nI would pity them, but they sought this out.\n\nYou, however, need to shift back before the influence of the Black Blood becomes too strong on your mind.", progress = "It is a relief that the tuning crystal we found worked on this strange instrument. For once we should be grateful for the ingenuity of the nerubians.\n\nIf this device had not worked, we may have been stuck in the Unseeming forever. Like the nerubians in the cave.", completion = "She can't keep running off like this! The rest of us followed her here--against our better judgement I might add--but we never agreed to...\n\n<Hannan sighs.>\n\nNo, we knew exactly what we were getting into with her. And the... consequences.", objectives = "Use the Harmonizing Instrument.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80568] = { id = 80568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave No Trace", description = "I need to go make sure she's all right. What I saw in that cave... If she's more sensitive to this...\n\n<Hannan nearly growls.>\n\nBut she's making a mess out here, drawing attention and leaving a trail leading outsiders right to her! Right to us.\n\nWe're supposed to be subtle. Unseen. Keep to the brush, hide in our other forms as much as possible.\n\nI hate to ask this of you, but can you use my scythe to take care of the evidence while I check on her?", completion = "It's forbidden for me to talk to outsiders, but... you have been helpful.\n\nThank you for aiding me with this burden.", objectives = "Collect 10 Magic Traces into Hannan's Scythe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80569] = { id = 80569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harmonious Approach", description = "I know I cannot stop Orweyna from going down there and drawing attention to our presence.\n\nBut... perhaps we could stop word of our presence from spreading.\n\nFind whoever is in charge of this harvest site. And... do what is needed to ensure they can't spread the word.", progress = "I'm not going to leave her down here alone. But we have to be cautious. We must deal with anyone who sees us.", completion = "I will admit, I am glad to have had you with us through all of this.", objectives = "Kill Harvest Warden Izk'tilak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80570] = { id = 80570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staunch the Flow", description = "Do they even understand what they are doing?\n\n<Orweyna bares her teeth, practically growling.>\n\nDestroy as many of those extractors as you can. Shatter the bulbs, snap the limbs, burn the wreckage.\n\nWe cannot stop them all, not today. But a bit of destruction may temper my rage.", completion = "They have already done so much damage. The creatures that once lived here, the earth that once thrived...\n\nIf we cannot stop them, we will take vengeance for that which they've destroyed beyond repair.", objectives = "Destroy 8 Extractors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80571] = { id = 80571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decipher the Cacophony", description = "This is far worse than I thought. It's as if they're feeding the corruption. Encouraging it. The dissonance growing louder and louder...\n\n<Orweyna seems shaken, but not deterred.>\n\nI can hardly hear anything else. My head is pounding. I... I need to see how far gone this land truly is.\n\n{name}. Bring me something from the Unseeming.", progress = "What have the nerubians done to this place?", completion = "This is wrong. This is all wrong.", objectives = "Collect 10 Discordant Essence from Discordant enemies in the Unseeming.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80572] = { id = 80572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discordant Measures", description = "I cannot stand to look at this any longer. I must act.\n\n{name}. You have survived the Unseeming before. Now we must go there together. I must see it for myself if I am to believe this vile place truly cannot be cleansed.\n\nWe will kill what we can and search for some sliver of hope that we can still restore this land.", progress = "Hannan's concerns are not unfounded.\n\nBut I cannot simply witness this corruption and make no attempt to root it out.", completion = "<Orweyna's voice is low with rage, but you see it is heartbreak shining in her eyes.>\n\nThis place is truly too far gone. There is no fixing what they have done here.", objectives = "Acquire 50 stacks of Unseeming Shift and collect 3 samples from elite enemies lost in the Unseeming.\n\nIn addition to destroying extractors, you can also acquire Unseeming Shift by standing in pools of Black Blood. However, be careful as you will gain stacks quickly by doing so.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80573] = { id = 80573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dropping Eaves: Spoils of War" }
quests[80576] = { id = 80576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Listener Lost", description = "Blast it all! \n\nBrennok and I were on our way to Shadowvein Point to conduct a recitation ceremony. We were attacked by scorpids. Now the hauler has a scorpid stinger lodged in its gears, and Brennok wandered off.\n\nHe said he was going to stretch his legs while I fixed the hauler, but that was a while ago. I need to get the bot moving again, can you look for him?", completion = "You don't understand, I was going to leave the Ringing Deeps. But I can't now, not without my book!", objectives = "Find Brennok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80577] = { id = 80577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Readying the Recitation", description = "Once a year, Brennok and I take the long road through The Ringing Deeps. \n\nWe stop at each outpost, and Brennok tells the residents a story from their past. One they entrusted to him to remember, even when they forget. \n\nIt's my duty to ready the ceremony site. Would you come with me? I could use the help.", progress = "Brennok usually seems more excited for a recitation.", completion = "Thank you. I hope you'll join us for the recitation when the time comes.", objectives = "Prepare the recitation site.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80578] = { id = 80578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Common Costume", description = "I'll slip away after the recitation. It's easy to vanish in a crowd of earthen enjoying a keg of cinderbrew.\n\nHowever, I can't be recognized when I leave town. I don't want anyone to stop me. Or worse, to think I'm abandoning my oath. Better to just disappear.\n\nIf you find me a spare set of Miner's Clothes, I'll be able to get away without being noticed.", progress = "Did you find them yet?", completion = "Thank you. No one should recognize me in these.", objectives = "Find a spare set of Miner's Clothes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80592] = { id = 80592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forge a Pact", description = "Let us renew your Pact.\n\nRemember, you may only enter a Pact with one of the Severed Threads at a time. These contracts are temporary, though, so you will have many opportunities to prove yourself to all three.", completion = "May your chosen patron favor you, as you have them.", objectives = "Choose a Severed Threads Pact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80593] = { id = 80593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sip of Cinder", description = "Now there's one last thing we need. It wouldn't be a proper recitation ceremony without mead. \n\nHowever, Hearthkeeper Zirc tells me the last couple deliveries of cinderbrew haven't arrived. It seems the local flayers in the Rumbling Wastes have a taste for it and raid the shipments.\n\nHere, take a spare keg. See what you can recover from the flayers.", progress = "Careful out there, flayers are already dangerous enough. I wouldn't want to meet one that's been guzzling cinderbrew.", completion = "Thank you, the miners will appreciate this. I hope the flayers weren't too much trouble.", objectives = "Fill a keg with Cinderbrew Mead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80670] = { id = 80670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes of the Weaver", description = "The Weaver's many eyes lurk throughout the city, learning as much as they can about Ansurek's machinations.\n\nStill, intelligence enough will not be sufficient to turn the tide against the Sureki forces. The Weaver requires someone willing to get their hands dirty.\n\nLucky you, I suppose.", progress = "Chk-chaah! You return at least. What news of the city do you bring me, hrm?", completion = "You have big talent for causing good trouble! Good good!\n\nTake these!", objectives = "Continue your efforts in aiding the Weaver in Azj-Kahet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80671] = { id = 80671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blade of the General", description = "Even now, General Anub'azal's forces work tirelessly to ensure the security of Azj-Kahet.\n\nAnsurek's reach extends to every corner of her domain. The General seeks to undermine her military authority. If we stretch her resources thin, then we may find new opportunities to strike.", progress = "Hrmph. It is about time that you've returned. What news?", completion = "You have returned alive, and the enemies of Anub'azal have not. \n\nThat is cause enough for recognition!", objectives = "Continue your efforts in aiding the General in Azj-Kahet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80672] = { id = 80672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hand of the Vizier", description = "The Vizier works even now to spread our conspiracy's influence amongst the well-to-do of Azj-Kahet's elite. Given his position, though, he can offer little in the way of direct support.\n\nThat is where you come in. Your growing reputation precedes you; you can move in ways that the Vizier cannot. Just take care not to get eaten, hrm?", progress = "I fear that our task grows more arduous with each passing day. I hope you are not wasting time.", completion = "Thanks to your efforts, the Vizier is one step closer to parity with the enemy. \n\nFor that, thanks are necessary.", objectives = "Continue your efforts in aiding the Vizier in Azj-Kahet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80673] = { id = 80673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runway Scare-a-way", description = "'Lo there.\n\nMe and Mags are generally in charge of clearing the sky in this area during our Lamplighting route. If we don't cull the moths in the area, they start spreading up towards the skydocks and start laying eggs in the machinery of our ships.\n\nUnfortunately we're not as spry as we used to be. Could you lend a helping hand? They're pretty frail so they'll squish easily to any high velocity flight. Or you could just smack 'em the old-fashioned way.", progress = "Nasty critters...", completion = "Kill one of 'em and four more somehow pop up. Well, this will help. We can take care of the rest.", objectives = "Kill 25 moths either by flying through them or killing them normally.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80676] = { id = 80676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defragmenting Memory", description = "My oath is to be a compiler. I collect and tell the stories of our people.\n\n<Brennok sighs.>\n\nIs there wisdom in stories told by someone who never lived them? I've never had an adventure. I was afraid to overwrite the stories entrusted to me.\n\nSo I started transcribing them into a book I hid here. Each time we returned to Shadowvein Point, I added more.\n\nI was going to leave and pass on the book, but scorpids ransacked it. Please, find the missing pages before they stuff them into their nests.", progress = "Thousands of stories, now they're probably lining some animal's den...", completion = "By the Titans, thank you! I don't know what I would have done if I'd lost these. \n\nI can finally leave without failing my oath.", objectives = "Collect 100 Missing Pages of Brennok's book.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80677] = { id = 80677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torching Lights", description = "No matter how many moths we swat, if we don't take care of the eggs they'll just continue to be a problem. \n\nTake this firearm, use it to torch some of the eggs on the top of the mire's canopy.", progress = "Watch the torch trigger, it's an older piece.", completion = "You would think they would learn to stay away from here. Yet they always come back.", objectives = "Torch 15 moth eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80678] = { id = 80678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time Lost", description = "Now that the job's done -- one thing I've always done on this route is muck around for some of the valuables that fall from the docks. As things get moved onto ships small items can fall off. Sometimes people chuck 'em for luck or in rage, and the like.\n\nBut some of those items have memories in 'em. Things so precious that losing it might as well be losing part of your heart. If you could help me look I'd be grateful.", progress = "What'd you find?", completion = "That's quite a haul. Take a few of these with you. Mayhaps you can find the owner of 'em.", objectives = "Find 6 lost mementos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80679] = { id = 80679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stuffed Lynx Toy", progress = "That item in your pack looks familiar...", completion = "Mr. Skinny! I thought you were lost forever!" }
quests[80680] = { id = 80680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarnished Compass", progress = "<The name on the compass from the Stagnant Mire matches one engraved in the epitaph of the community gravestone.>", completion = "<The world is silent save for the distant hum of airships. \n\nDespite the damage left by time and nature, the needle still points towards Beledar.>" }
quests[80681] = { id = 80681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Bracelet", progress = "What is it you have there?", completion = "That is... \n\n<Keyrra carefully places the bracelet in her palm.>\n\nI can't believe it." }
quests[80682] = { id = 80682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Last Story", description = "Well, it's time. I'll be holding the recitation at the mine entrance. I'll see you there, though don't feel obligated to stay the whole time.\n\nI'll leave my book for Haimaz to find. She'll take care of it.\n\nAfter the ceremony, I would like to say goodbye properly. Meet me by the bridge outside of town. I'll head there after the recitation.", completion = "I knew Brennok was acting odd. Then one of the miners mentioned you'd borrowed a spare set of clothes. That and his strange mood, well, it wasn't hard to guess that he planned to leave.\n\nI expected him to come this way, though. Have you seen him?", objectives = "Attend the recitation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80684] = { id = 80684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gently Shaken Gift", objectives = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special {race} {class}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80685] = { id = 80685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Winter Veil Gift", objectives = "A small tag on this present reads:\n\nHappy holidays, {name}!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80687] = { id = 80687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[80689] = { id = 80689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tending to Ausgazur", description = "Assigned tasks complete! I'll check back on these folks on my next scheduled patrol.\n\nThere is one more earthen I must tend to today. He was... he is very special to me.\n\nYou've been an especially considerate colleague, so I'd like for you to see him. Let us travel west a bit, closer to the falls.", completion = "You made it! \n\n<She looks at the outstretched hand of the earthen next to her and sighs.>\n\nI admit that I am quite disturbed by what I've found here. Your presence is a comfort.", objectives = "Meet Batzvara in Shimmermist Falls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81465] = { id = 81465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifacts Galore" }
quests[81470] = { id = 81470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dropping Eaves: Thieving Weave" }
quests[81471] = { id = 81471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dropping Eaves: Saving the Past" }
quests[81472] = { id = 81472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Information Control: Ansurek's Truth" }
quests[81473] = { id = 81473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Information Control: The Right Side of History" }
quests[81475] = { id = 81475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Phalanx: Royal Appointees", objectives = "Kill 4 Royal Appointments in the Skeins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81476] = { id = 81476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bounty: Chitinous Goliath" }
