quests[81630] = { id = 81630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Activation Protocol" }
quests[81632] = { id = 81632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lizard Looters", description = "Despite the punishment of our posting here, life isn't entirely unpleasant. Captain Lancekat left us a generous supply of provisions. \n\nWell, at least she did until recently. A sizable lizard has made off with our camp supplies!\n\nCould you recover our camp supplies and deal with the pilfering thief?", progress = "Did you find the supplies?", completion = "Fine work, we'll drink to your success as we feast on these supplies.", objectives = "Slay Reekscale and recover 8 Camp Supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81638] = { id = 81638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home Is Where the Hearthstone Is", objectives = "Welcome to our humble village.\n\nI can give you a hearthstone to return here if you ever need a place to rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81639] = { id = 81639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honey Thieving Nerubians" }
quests[81640] = { id = 81640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tenir and the Order of Night", description = "<A script for an epic stage play. Stage Manager Huberta on the Isle of Dorn may have interest in this.>", completion = "Very interesting, I will add this to my collection of unread submissions.", objectives = "Deliver this to Stage Manager Huberta on the Isle of Dorn.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
