quests[81651] = { id = 81651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Guide to Delves", description = "Greetings! Up for going through some delves in the area?", sourceObjective = "Reach the Sinkhole and Mycomancer Caverns", sourceObjectiveStatus = "unverified-source-field" }
quests[81653] = { id = 81653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shurrai, Atrocity of the Undersea" }
quests[81654] = { id = 81654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Harbinger", description = "We are in need of your aid once more, champion. A mysterious figure moves within the shadows. The Harbinger...\n\nLet us speak in the Chamber of the Guardian. I've asked Alleria to meet us there as well.", progress = "A Radiant Song, a Dark Heart, and this mysterious Harbinger... What could it all mean?", completion = "We know Iridikron gave the Dark Heart to the Harbinger. But what the Dark Heart is, what the Harbinger plans to do with it... Those are mysteries still.\n\nAnd the Radiant Song. Its timing is no coincidence.\n\nThis matter can no longer wait. That is why I've asked you and Alleria to investigate.", objectives = "Meet Khadgar and Alleria in the Chamber of the Guardian in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81655] = { id = 81655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Juicy Krolusk Meat", description = "Greetings! I am Kagfritha. I was once a site supervisor for operations in the Rumbling Wastes to the south of here, but time has taken its toll on our enterprise and we had to abandon the area. \n\nIt's high time we got things back in working order down there, but while we were gone some unsavory creatures moved in. I have a plan for dealing with the worst of the bunch, but first we need some bait. \n\nIf you're here to help, go hunt some of those dirt diving krolusks and bring me back their meat.", progress = "I have big plans for that krolusk meat, and for the Rumbling Wastes!", completion = "Ah, these juicy hunks of flesh are exactly what I need!", objectives = "Collect 4 pieces of krolusk meat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81656] = { id = 81656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nothing to Waste" }
quests[81661] = { id = 81661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Mourning Rise", description = "Greetings, outlander. My name is Urtago, and I am Caretaker Korgran's apprentice at the Mourning Rise memorial site.\n\nThe mischievous Candlelit Kobolds have overrun Mourning Rise, and we seek assistance. Would you meet me at Fallside Outpost? It is just to the north of here. I will be able to tell you more once you arrive.", completion = "You are here! Thank you for coming.", objectives = "Meet Urtago at Fallside Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81667] = { id = 81667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Upstart", description = "You are the Weaver's \"untethered third party?\" Excellent. You are the perfect catalyst for a coup.\n\nThe City of Threads has sent an upstart here to seize control of Rak-Ahat. \n\nThe arrival of Ren'khat has everything all tangled up. He postures himself as some kind of silk visionary from the city, and he challenges the authority of the Overspinner who refused to relinquish control. \n\nBad for the Overspinner, good for us. Speak with Ren'khat and feed his ambition. Help him against the Overspinner.", progress = "What is this? An overcrawler? Here?", completion = "You... you are willing to help me achieve the brilliance of my art? \n\nAnd you have no ties that could be traced back to me? \n\nPerfect!", objectives = "Offer your services to Ren'khat against Grand Overspinner Antourix.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81668] = { id = 81668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Measure Once, Cut Thrice", description = "I was promised an important, glamorous, enviable position of power when I left the city for Rak-Ahat.\n\nThis warehouse job? Neither important nor enviable. And certainly not glamorous.\n\nGrand Overspinner Antourix has been at this for far too long. She doesn't understand my vision. All she wants are drones that do exactly what she wants, how she wants it.\n\nTake out her most loyal workers. We'll see how tough she is on her own once I take over the dyeworks.", progress = "Ugh. It's impossible to work under these conditions.", completion = "With those sycophants out of the way, the Overspinner is nothing. I'll be running this place in no time.", objectives = "Slay Webwarper Tath'rhiz, Seam Reaper Zhir'ix, and Colormancer Nirethi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81669] = { id = 81669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sticks and Bones", description = "While the krolusks like to attack from beneath, the Rumbling Waste also plays host to a predator who prefers to swoop down from above. Deepsflayers have built nests on the peaks and ridges around the Waste. \n\nDestroy their nests and show them that the Waste is no welcoming home.", progress = "Let's show those overgrown bats that the Wastes is no home for them!", completion = "I could see the smoke from here! Good job! That ought to make those wretched things look for a new place to perch.", objectives = "Burn 6 Deepsflayer Nests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81670] = { id = 81670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shattered Silk", description = "Nothing will get the attention of the Head Cutter--and disrupt her operations--like destroying her equipment! Get in there and mess stuff up, really send a message.", objectives = "Bar fill destroy EVERYTHING kill EVERYONE", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81672] = { id = 81672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In a Pinch", description = "I suppose I should come clean and tell you why I had you gather that meat.\n\nTruth is, there's a horrible beast who lives down in the Wastes. A monster who feeds on the unwary and whose pincers can snap through stone and bone like a knife through warm butter. \n\nIts name is Smaragthr, and the foul thing is the reason I have but one eye and my gems are cracked. I am no match for it, but you... you could enact my vengeance. \n\nKill Smaragthr so the Wastes can be free!", progress = "I will have my revenge on that vile creature!", completion = "You did it! I hope you made it hurt.", objectives = "Kill Smaragthr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81673] = { id = 81673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor Your Efforts", description = "Though my rank is humble, I bestow upon you this honor. A tinderbox, signifying your friendship with our expedition and your esteemed status in Hallowfall. \n\nShould you fall in battle, your tinderbox shall be given a place of honor among the other great heroes who died defending this land.\n\nPlease accept this honor.", progress = "You should be proud of your efforts.", completion = "May the Sacred Flame protect you.", objectives = "Accept the honor of a Hallowfall Tinderbox.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81675] = { id = 81675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water the Sheep" }
quests[81683] = { id = 81683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spring Collection", description = "That maggot Ren'khat wants my position, hm? He's welcome to try and take it.\n\nAll the runoff from our operation flows into the spring below Rak-Ahat. Decades of mordants, catalysts, and alchemical concoctions have coalesced into something quite... potent.\n\nDon't fuss about the side effects. Just bring me a good variety of dyestuffs and I'll brew up colors that will have you growing extra pairs of legs.", progress = "You're still here?", completion = "I think these will do. You're not as useless as I expected.", objectives = "Collect 12 Reclaimed Catalyst, as well as 3 Luminous Strangler Sap, 3 Eyeless Petals, and 3 Cochineal Crawlers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81685] = { id = 81685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azj-Kahet's Next Top Dyemaster", description = "Ren'khat and the Overspinner are fighting pincer-and-claw. Inside the spinneret. With no witnesses.\n\nWe have a unique opportunity here. If they took one another out... well, with Antourix's favorites dispatched and the whole of Rak-Ahat in disarray, the next best authority would be the caravan coordinator. Me.\n\nI don't love being in the spotlight, but it would be very beneficial to our secret-smuggling operation if those two didn't make it out of the dyeworks.", progress = "What a relief not to hear those two bickering anymore...", completion = "The sheer scandal will have the record-keepers in the City of Threads busy for months.\n\nAnd I'll make sure they don't look too closely at how it happened.", objectives = "Slay Ren'khat and Grand Overspinner Antourix.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81686] = { id = 81686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subterfuge in Silk", description = "I'm expecting a shipment of silk. That it hasn't arrived worries me.\n\nMost silk in Azj-Kahet, from the finest veils to the strongest warsilk, comes from Rak-Ahat. It makes the place a convenient nexus of information.\n\nOne of my agents smuggles military secrets woven into the silk itself. Recently, she has reported a power struggle emerging in Rak-Ahat... and even more recently, she has reported nothing at all.\n\nMeet with her and ensure no more delays.", completion = "I see our mutual \"friend\" got my message and sent you to aid.\n\nOur production schedule is shot as our management struggles to assert itself.\n\nI propose this chaos is fertile ground for the ambitious.", objectives = "Meet with Teth at Rak-Ahat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81687] = { id = 81687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Expect You To Dye", description = "I thought playing them against each other would give me some cover, but it's plunged all of Rak-Ahat into chaos! This could jeopardize our whole operation!\n\nYou heard what Antourix said. She already augmented the dyebaths with all of those reagents you collected. I don't know what they'll do, but if she was planning on using them against Ren'khat... there's no reason you couldn't use them to take out both of their goons.\n\nTest out those dyebaths, and clear out the dyeworks!", progress = "I wanted less squabbling interfering with my work, not more!", completion = "Some equipment broken, some laborers scared... but most importantly, all of their lackeys are out of the way. I'll take that as a victory.", objectives = "Slay 8 Dyeworks nerubians using the powers granted by Augmented Dyebaths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81688] = { id = 81688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's All", description = "It will be interesting to see how all this unfolds... but knowing the Weaver, I'm sure she has some strings to pull to make it go her way.\n\nThis is the secret I was trying to pass to her when things started heating up. Why don't you deliver it to her, as a sign of a job well done?\n\nI'm sure she'll be pleased to know that she continues to have a set of eyes in Rak-Ahat.", completion = "Aha, I admit I hadn't expected to receive this.\n\n<The Weaver runs her pedipalps over the secret-woven silk, delighted.>\n\nVery interesting. I will have to keep this in mind.", objectives = "Deliver the Secret-Woven Silk to the Weaver in her lair.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81689] = { id = 81689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orientation: Gundargaz", description = "Our new kobold friends have been moving into Gundargaz. They've also been gathering odds and ends from around the Ringing Deeps.\n\nYou should check in with the Quartermaster! Go have a look at what they've collected. Then we can talk about what we're doing next. \n\nI heard Anduin's around here somewhere. I suspect he has some plans for Hallowfall. We need all the allies we can get against the nerubians.", progress = "New allies are always appreciated.", completion = "It's good to make new friends. In the days ahead, we'll need all the help we can get.", objectives = "Meet with Waxmonger Squick in Gundargaz", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81690] = { id = 81690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Light at the End of the Tunnel", description = "I've never seen shadows this deep. This... vicious. \n\nIt almost feels like they're reaching for us. \n\n<Faerin shudders.>\n\nWe can't stay here.", completion = "I'm glad you're safe. I sensed something amiss when those creatures suddenly stopped attacking the tower and disappeared. Beledar shifted on its own shortly after. \n\nThat was no simple illusion Xal'atath trapped you in. I wonder, was I its intended target? \n\nYou, me, Anduin, Faerin... perhaps she was happy to ensnare any of us.", objectives = "Escape Gloomcrag Bower with Faerin and Anduin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81691] = { id = 81691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Shadows Below" }
quests[81692] = { id = 81692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flame Within", description = "When sparked, a tinderbox creates a flame that embodies the essence of its bearer's life journey. It is a reflection of your strength and inner spirit.\n\nIn your travels, you have met many who could help us fashion a tinderbox capable of igniting a flame befitting your formidable spirit.\n\nSeek the assistance of Speaker Kuldas in Gundargaz. The earthen's knowledge will help create a more powerful tinderbox.", completion = "You were correct to seek my assistance. As a machine speaker there are few problems I cannot solve.", objectives = "Seek out and gain the aid of Speaker Kuldas in Gundargaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81693] = { id = 81693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperately Seeking Skorthuz", description = "Eh? Who are you? Oh that's right, I heard that there were new folk about.\n\nSay, are you heading north? If so, keep an eye out for my friend, Skorthuz, will you? The laggard was due back an hour ago but is nowhere to be seen. I heard he was heading towards the Chittering Den for some awful reason. \n\nIf you see him, tell him to hurry up and get back here or I'm drinking alone!", completion = "Who are you? Oh, Hrandaz sent you? Is it that time already?", objectives = "Look for Skorthuz around the Chittering Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81696] = { id = 81696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to the Trading Post (D)", description = "Quest Description", objectives = "Return to the Trading Post to collect your Trader's Tender from the Collector's Cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81710] = { id = 81710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mead for the Catalog" }
quests[81711] = { id = 81711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creature Name" }
quests[81712] = { id = 81712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lisky Business", description = "Hrandaz is going to have to wait. My beloved Lisky is missing! She went into this cave and hasn't come out. I think whatever's making that terrible stench drew her attention. \n\nPlease, go in and find my Lisky? She hasn't drawn the attention of the horrid creatures inside yet, but it's only a matter of time!", progress = "My sweet precious Lisky! Please get her out of there.", completion = "You found her! Thank you!", objectives = "Rescue Lisky from the cave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81713] = { id = 81713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oozemodious", description = "I tried to get Lisky back myself, but she ran to the far end of the cave. The whole thing is full of disgusting masses of worms. \n\nAs if they aren't bad enough, down the back there's a creature so vile and slimy and oozy that I ran for my life!\n\nNo, I am not proud of leaving Lisky behind. I was just about to work up the courage to get back in there when you arrived. While you're looking for Lisky, you should dispose of those gross things in there! I'm pretty sure they're multiplying!", progress = "I am counting on you to do this dirty work. If I'm behind honest, I have an irrational fear of worms and sticky things. \n\nI much prefer dry, solid, gritty creatures. Especially if they have nice hard scales!", completion = "You did it! It's a mystery as to how you're not completely covered in slime yourself now.", objectives = "Kill 6 slimes and Oozemodius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81714] = { id = 81714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to the Trading Post", objectives = "We hope you like this month's collection of new and exotic wares, {name}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
