quests[81748] = { id = 81748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid the Sunreavers Onslaught", progress = "My scouts report enemy activity. Have you any supplies to bring fortune to our troops?", completion = "Very good, we shall ready a counterattack." }
quests[81749] = { id = 81749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid the Kirin Tor Offensive", progress = "There will be no victory without bloodshed. Have you brought aid, {class}?", completion = "I will add these to the coffers." }
quests[81750] = { id = 81750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloud Farming" }
quests[81751] = { id = 81751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire and Gemstone", description = "What's this? A tinderbox? \n\nI've heard tell of these Arathi contraptions, but have never held one in my hands. It's smaller than I would have thought...\n\nUpgraded, you say? Ha! We can do that. The next time we're Awakening the Machine, keep an eye out for an Awakened Cog and Ringing Gemstone.", progress = "Have those items for me?", completion = "You've got them! Cogs be praised and gears be ground, let's see what we can do with this magical little doodad of yours.", objectives = "Acquire an Awakened Cog and a Ringing Gemstone from Awakening the Machine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81767] = { id = 81767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrounge that Scrap!" }
quests[81793] = { id = 81793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparks of War: Isle of Dorn", description = "Powerful creatures are causing havoc across the Isle of Dorn. \n\nGet out there and clear things up!", progress = "Best time to start is now.", completion = "Our watch can finally continue without obstruction. Many thanks.", objectives = "Collect 100 Sparks of War in Isle of Dorn, while in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81794] = { id = 81794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparks of War: The Ringing Deeps", description = "Unseen forces have overrun multiple Earthen outposts. \n\nSeek them out and cleanse the deeps.", progress = "How goes the recovery?", completion = "You survived the deep well!", objectives = "Collect 100 Sparks of War in The Ringing Deeps, while in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81795] = { id = 81795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparks of War: Hallowfall", description = "The light beneath is fickle, but it will save you from the dark if you master it.\n\nGo. Travel to Hallowfall, and lend your strength to the Arathi.", progress = "Be wary of the dark.", completion = "The Arathi people now have a moment of peace, thanks to you.", objectives = "Collect 100 Sparks of War in Hallowfall, while in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81796] = { id = 81796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparks of War: Azj-Kahet", description = "We've received strange readings coming Azj-Kahet.. Investigate these locations, but stay vigilant.", progress = "Go off and complete your investigation.", completion = "YOU SURVIVED? And with all your limbs no less. Well done.", objectives = "Collect 100 Sparks of War in Azj-Kahet, while in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81797] = { id = 81797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Targeted Recon", description = "If you've spent much time in Hallowfall, no doubt by now you've run across the foul magic of the kobyss. Reports that their illusions have been evolving are fiercely debated within the Arathi Army.\n\nYour outside perspective is just what I'm looking for. Venture to the Sunless Strand, slay a few of their illusory assassins, and then report your findings. You'll likely find them hiding in the shadows.", completion = "Their illusory projections of Arathi civilians sound convincing as ever. I struggle to understand how such vicious and undiplomatic creatures can emulate Arathi mannerisms so well.\n\nNonetheless, this is all in line with our current understanding of the kobyss. Your report shall be put to good use. Thank you, outsider.", objectives = "Slay three Kobyss Shadeshapers in Sunless Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81798] = { id = 81798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Moira", description = "Speaker Brinthe's impulsiveness is getting the better of her. \n\nYou'd best return to your comrades and let them know of her intentions!", completion = "{name}! You're back. Let us end this charade.", objectives = "Return to Moira in the Earthenworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
