quests[81869] = { id = 81869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can Catch More Fires with Honey", description = "Crafting with flame demands a fuel that burns pure and has sustainable power. Among these, the honey created by Cinderwold bees stands out! A source of elemental fire, organic and untainted.\n\nI've longed for a supply of this honey, yet never had the chance to procure it. \n\nTake my harvesting device and gather a quantity for our purpose. We shall infuse it into your tinderbox. Exercise caution, for some of the earthen revere these bees as sacred creatures.", progress = "Have you acquired the honey?", completion = "So sweet and the flame jumps from it even now. This should make an excellent fuel for your tinderbox!", objectives = "Collect 10 Pure Fire Honey from the Overladen Drones in Cinderwold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81886] = { id = 81886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Alliance", description = "For the first time in our history, the outside world is ours to explore and experience.\n\nAn off-island faction known as the Alliance came to the aid of our kin. Valiant and wise, the stalwart Alliance has extended an open hand to our people.\n\nWill you be among the first to accept and visit their lands, learn their histories and walk amongst their people?\n\nIf that path calls to you, then I hope you'll return to share those experiences and show the earthen what the world has to offer.", completion = "Well, here we are! Another {race} from... Khaz Algar, is it?\n\nA couple of Wildhammers sent word that some of your people might be coming to visit.\n\nWell, make yourself at home here in town. The Alliance welcomes all of its new friends with open arms. \n\nWelcome to Stormwind!", objectives = "Meet Ambassador Moorgard at the Stormwind Embassy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81887] = { id = 81887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranger in a Strange Land", description = "Welcome to Stormwind, {race}. I invite you to explore our fair city. Say, you look like someone who appreciates fine stonework! We have many impressive stone buildings and walls.\n\nAh, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things!\n\nAfter that, an emissary of yours is waiting to welcome you to the city. Sounds like a busy day for you!\n\nHave a pleasant stay, {name}!", progress = "Greetings, {name}.", completion = "Welcome to Stormwind. Acclimate yourself and learn all you can.\n\nOur experiences will be invaluable to the Archives back in Dornogal.", objectives = "Talk to Chromie in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81888] = { id = 81888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Horde", description = "For the first time in our history, the outside world is ours to explore and experience.\n\nAn off-island faction known as the Horde came to the aid of our kin. Spiritual and mighty, the honorable Horde has opened their hand to our people.\n\nWill you be among the first to go where no earthen has ever gone? To walk their lands, hear their songs and learn from their people?\n\nIf that path calls to you, then I hope you'll return to share those experiences and show the earthen what the world has to offer.", completion = "What's this then? An... {race}? I heard we might be seeing some of your people here.\n\nWell, make yourself at home if you can. \n\nWe have plenty of rocks in this sweltering place, so I guess if that's your thing...you'll do just fine.\n\nJust...don't eat the rocks. Do you even eat rocks?\n\nEither way, welcome to Orgrimmar.", objectives = "Meet with Ambassador Blackguard at the Orgrimmar Embassy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81889] = { id = 81889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranger in a Strange Land", description = "Hi. I'm Ambassador Blackguard.\n\nI am honored to welcome you to Orgrimmar, {race}.\n\n<He smiles unconvincingly.>\n\nAs a lifetime of adventure unfolds before you, be assured that... uh...\n\nYou know what? I've been saying this same greeting all day. Enough's enough.\n\nTalk to Chromie on top of the hourglass, then talk to your emissary. Run along.", progress = "Greetings, {name}.", completion = "Welcome to Orgrimmar. Acclimate yourself and learn all you can.\n\nOur experiences will be invaluable to the Archives back in Dornogal.", objectives = "Talk to Chromie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81890] = { id = 81890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfulfilled Requests", description = "I have heard the citizens of the Silken Ward are having trouble with a group of Ascended called the Pale Weavelashers.\n\nThe new ward is supposed to be a fresh start for citizens of the capital, at least that is the way the Queen tells it. In actuality it is a way for her to tighten her grip on those she distrust. \n\nMeet with my assistant Sum'latha. I sent her there ahead of time to gather information. She can fill you in on any details.", completion = "You must be the help the Vizier sent. Welcome to the Silken Ward.", objectives = "Meet with Sum'latha at the Silken Ward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81896] = { id = 81896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New and Improved", description = "I've completed the modifications. I must say, this is some of my finest work! \n\nDespite its modest design, a bit of cog grease and elbow dust has transformed it into a device that even the surliest of the flame worshippers could appreciate.\n\nIf any of them want to know how it's done, send them my way.", completion = "The fire of this tinderbox will now burn brighter than ever!", objectives = "Accept the new improved Tinderbox from Kuldas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81906] = { id = 81906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispers from the Web", description = "Hey! Hey!\n\n<The girl waves her arms to get your attention, a scrap of paper clutched in one hand.> \n\nYou won't believe me, but I found the cutest, fuzziest puppy! With a bell! Around its neck!\n\nIt gave me this to give to you. Take it, I gotta go catch that puppy!\n\n<The missive is written in elegant script, calling you to Azj-Kahet.>", completion = "I see my message reached you. You are... not quite as imposing as I had imagined, but rumor has it that your skills are unmatched.", objectives = "Meet with Ct'nak in the Burrows of Azj-Kahet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81908] = { id = 81908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Flame in the Dark", description = "Contained within the Underkeep lies a tinderbox, once belonging to the late Aelric Leid.\n\nThis item reeks of powerful, corruptive energy. Its close proximity has leeched out to touch many nerubians.\n\nYour task is to retrieve that box and deliver it to me. To be safe, gather any tinderboxes you may find--we'll destroy them all, just in case.", progress = "Did you find the tinderboxes?", completion = "Quickly, give it to me--we should not allow it to be seen in public!", objectives = "Search various containers inside the Underkeep for 8 Unidentified Tinderboxes and Aelric's Corrupted Tinderbox.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81909] = { id = 81909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Absolute Power", description = "The dark allure of this item surpasses my initial expectations. I can sense a surge of power coursing through me. \n\nWe must delve deeper into its mysteries.\n\nHowever, it is unwise to discuss this matter openly. Follow me inside, where we may deliberate further.", progress = "What's that you have there?", completion = "This is most unexpected. Where on earth did you find it?", objectives = "Discuss the tinderbox's destruction with Ct'nak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81910] = { id = 81910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Great Responsibility", description = "To witness such corruption is deeply unsettling. \n\nDespite the dark energies intertwined with this tinderbox, there remains a flicker of the Sacred Flame, struggling to escape. I will not destroy that flicker, champion. \n\nYet I dare not hold onto it any longer. \n\nPerhaps your purity of spirit can withstand the darkness it holds. Please, {name}, carry it with you. Protect that small spark of purity, and help it break free of the dark magic that ensnares it.", completion = "I place in your care this small ember of hope, along with the weighty responsibility to safeguard it.", objectives = "Accept the tinderbox.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81912] = { id = 81912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight Training 102", description = "Dunnae think I had nae noticed those rooks spittin' lightnin'. Sure beats tossin' hammers. But it won't mean nothin' if the Stormriders can't hit what they're fightin'.\n\nLet's test their aim. Got some gnomish contraptions here that'll project easy targets for practice. Take Shraubendre back out there an' show them how it's done!", progress = "Flyin' takes a firm hand. An' boy do these earthen have that!", completion = "Now, that's the stuff! Did a real number on those projectors. But what we really need is a movin' target.", objectives = "Help Kurdran train recruits in aerial targeting.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81913] = { id = 81913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight Training 103", description = "These recruits seem tae be up for a challenge. Let's find them somethin' with a little bite!\n\nI saw a poor giant just off shore bein' pestered by a swarm of flying devils. Let's see if these rooks can shoot the wings off 'em an' provide some relief.\n\nYou and Shraubendre are settin' a good example for the rest. Keep it up!", completion = "The training went well, did it? I'm sorry I wasn't there for it. There was just something I had to do.", objectives = "Help Kurdran train recruits in aerial combat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
